afterAll(() => cleanup());

it("freezes", async () => {
  const t = await createTenant("frz");
  await usageRepo.recomputeUsage(t.org.id);
  const owner = t.actors.owner;
  const issue = await issueService.createIssue(owner, issueInput(t.org.id, t.project.id, { title: "x", dueAt: "2020-01-01T00:00:00.000Z" }));
  const comment = await commentService.createComment(owner, { orgId: t.org.id, issueId: issue.id, body: "hi", parentId: null, mentionedUserIds: [] });
  const att = await attachmentService.addAttachment(owner, { orgId: t.org.id, issueId: issue.id, filename: "a.txt", contentType: "text/plain", sizeBytes: 10 });
  await projectService.archiveProject(owner, { orgId: t.org.id, projectId: t.project.id, archiveIssues: false });
  const events: string[] = [];
  const offs = ["issue.updated","issue.status_changed","issue.assigned","issue.archived","comment.created","comment.deleted","issue.overdue"].map((e) => subscribe(e as never, () => { events.push(e); }));
  const ops = [
    () => issueService.updateIssue(owner, { orgId: t.org.id, issueId: issue.id, title: "y" }),
    () => issueService.changeIssueStatus(owner, { orgId: t.org.id, issueId: issue.id, status: "done" }),
