  ];
  for (const op of ops) await expect(op()).rejects.toBeInstanceOf(AlreadyArchivedError);
  await expect(issueService.updateIssue(t.actors.viewer, { orgId: t.org.id, issueId: issue.id, title: "y" })).rejects.toBeInstanceOf(PermissionDeniedError);
  await issueService.getIssue(owner, t.org.id, issue.id);
  await commentService.getThread(owner, t.org.id, issue.id);
  await attachmentService.listAttachments(owner, t.org.id, issue.id);
  await issueService.getBoard(owner, t.org.id, t.project.id);
  const r1 = await runOverdueIssueJob(new Date());
  expect(events).toEqual([]);
  await projectService.restoreProject(owner, t.org.id, t.project.id);
  await runOverdueIssueJob(new Date());
  expect(events).toEqual(["issue.overdue"]);
  await issueService.updateIssue(owner, { orgId: t.org.id, issueId: issue.id, title: "y" });
  expect(events).toContain("issue.updated");
  offs.forEach((o) => o());
  void r1;
});
